import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerReels() {
    const navigate = useNavigate();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Initialize Remix Icons if available
        if (window.RemixIcon) {
            window.RemixIcon.init();
        }
        
        loadSellerReels();
    }, []);

    const loadSellerReels = async () => {
        try {
            setLoading(true);
            
            // Get seller reels from API
            // Note: In a real app, you would get the vendor ID from auth context or props
            const vendorId = 1; // Placeholder - in real app this would come from auth
            const response = await ApiService.getSellerReels(vendorId);
            
            if (response.success) {
                // Fetch product names for all reels
                const reelsWithProductInfo = [];
                
                // Process each reel to get product information
                for (const reel of response.data) {
                    // Get product IDs from the reel
                    const productIds = reel.product_ids || [];
                    
                    if (productIds.length > 0) {
                        // For each product in the reel, create a separate entry
                        for (const productId of productIds) {
                            reelsWithProductInfo.push({
                                ...reel,
                                productId: productId,
                                productName: 'Loading...', // Will be updated with actual name
                                reelCount: 1 // Each reel represents one product-reel combination
                            });
                        }
                    } else {
                        // Handle reels with no products (fallback)
                        reelsWithProductInfo.push({
                            ...reel,
                            productId: null,
                            productName: 'Unknown Product',
                            reelCount: 1
                        });
                    }
                }
                
                // Now fetch product names for all product IDs
                const allProductIds = [...new Set(reelsWithProductInfo.map(r => r.productId).filter(id => id))];
                if (allProductIds.length > 0) {
                    try {
                        const productNamesResponse = await ApiService.getProductNamesByIds(allProductIds);
                        if (productNamesResponse.success) {
                            const productNamesMap = productNamesResponse.data;
                            
                            // Update product names in the reels
                            const updatedReels = reelsWithProductInfo.map(reel => ({
                                ...reel,
                                productName: reel.productId && productNamesMap[reel.productId] 
                                    ? productNamesMap[reel.productId] 
                                    : reel.productName
                            }));
                            
                            setReels(updatedReels);
                        }
                    } catch (error) {
                        console.error('Error fetching product names:', error);
                        // Continue with default product names
                        setReels(reelsWithProductInfo);
                    }
                } else {
                    setReels(reelsWithProductInfo);
                }
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading seller reels:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
            
            // Fallback to sample data in case of error
            setTimeout(() => {
                const sampleReels = [
                    {
                        id: 1,
                        productName: 'Summer Dress',
                        reelCount: 1,
                        title: 'New Summer Collection',
                        category_name: 'Fashion',
                        status: 'approved',
                        views: 1250,
                        likes: 342,
                        created_at: '2023-06-15T10:30:00Z',
                        date: '2023-06-15'
                    },
                    {
                        id: 2,
                        productName: 'Winter Coat',
                        reelCount: 1,
                        title: 'Winter Sale Announcement',
                        category_name: 'Seasonal',
                        status: 'pending',
                        views: 0,
                        likes: 0,
                        created_at: '2023-06-18T09:45:00Z',
                        date: '2023-06-18'
                    },
                    {
                        id: 3,
                        productName: 'Spring Shoes',
                        reelCount: 1,
                        title: 'New Arrival: Spring Shoes',
                        category_name: 'Footwear',
                        status: 'approved',
                        views: 2100,
                        likes: 567,
                        created_at: '2023-06-10T16:20:00Z',
                        date: '2023-06-10'
                    }
                ];
                setReels(sampleReels);
            }, 500);
        }
    };

    const handleViewReelVideo = async (reelId) => {
        // Navigate to the view page for this specific reel
        navigate(`/studio/seller/reels/${reelId}`);
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    const formatDate = (dateString) => {
        if (!dateString) return 'N/A';
        return new Date(dateString).toISOString().split('T')[0];
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                        {/* Removed Upload Reel button */}
                    </div>
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                <Link to="/studio/seller/upload" className="btn btn-success">
                                    <i className="ri-upload-line me-1"></i> Upload Reel
                                </Link>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Product Name</th>
                                            <th>Reel Count</th>
                                            <th>Title</th>
                                            <th>Category</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((reel) => (
                                            <tr key={`${reel.id}-${reel.productId}`}>
                                                <td>{reel.productName}</td>
                                                <td>{reel.reelCount}</td>
                                                <td>{reel.title}</td>
                                                <td>{reel.category_name || 'N/A'}</td>
                                                <td>{getStatusBadge(reel.status)}</td>
                                                <td>{reel.views || 0}</td>
                                                <td>{reel.likes || 0}</td>
                                                <td>{formatDate(reel.created_at)}</td>
                                                <td>
                                                    <button 
                                                        className="btn btn-sm btn-info"
                                                        onClick={() => handleViewReelVideo(reel.id)}
                                                        title="View Reel"
                                                    >
                                                        <i className="ri-eye-line"></i> View
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
